def format_value(name, value):
    """Apply a format using its original SAS name, including any $ prefix."""
    return lookup(FORMATS, name, value, MACROS)


def ODDENOM(value):
    """Apply the original SAS ODDENOM format."""
    return format_value('ODDENOM', value)


